insert into templates (id, name, required_docs) values
  ('shortage_wmt', 'Shortage (Walmart)', '[{"doc": "pod", "points": 12, "when_terms": "prepaid"}, {"doc": "bol", "points": 12, "when_terms": "collect"}, {"doc": "po", "points": 12}, {"doc": "invoice", "points": 11}]'::jsonb),
  ('shortage_amz', 'Shortage (Amazon)', '[{"doc": "delivery_confirmation", "points": 18}, {"doc": "invoice", "points": 17}]'::jsonb),
  ('pricing_wmt', 'Pricing (Walmart)', '[{"doc": "invoice", "points": 12}, {"doc": "claim", "points": 12}, {"doc": "po", "points": 11}]'::jsonb),
  ('asn_amz', 'ASN compliance (Amazon)', '[{"doc": "asn_file", "points": 35}]'::jsonb),
  ('carton_amz', 'Carton and label (Amazon)', '[{"doc": "carton_photo", "points": 35}]'::jsonb);
insert into template_lines (id, template_id, line_no, bucket, label, points, check_key, fatal, fatal_verified, why, fix, fix_owner, source) values
  ('shortage_wmt-1', 'shortage_wmt', 1, 'Evidence present', 'Required documents present', 35, 'docs_present', true, true, 'A dispute without its required documents is denied.', 'Attach the missing document.', 'analyst', 'https://www.spscommerce.com/community/articles/why-deduction-documents-get-rejected-fixes'),
  ('shortage_wmt-2', 'shortage_wmt', 2, 'Evidence content', 'PO number matches', 8, 'po_matches', false, false, 'Every document must point to the PO being disputed.', 'Get a corrected copy showing the right PO number.', 'logistics', 'https://help.supplypike.com/en/articles/4993182-example-shipping-documents'),
  ('shortage_wmt-3', 'shortage_wmt', 3, 'Evidence content', 'Ship-to matches', 8, 'shipto_matches', false, false, 'The delivery address must match the PO''s ship-to location.', 'Confirm the delivery location with the carrier and get a corrected copy.', 'logistics', 'https://help.supplypike.com/en/articles/4993182-example-shipping-documents'),
  ('shortage_wmt-4', 'shortage_wmt', 4, 'Evidence content', 'Stamp or signature present', 9, 'proof_signed', true, true, 'Walmart treats a POD without a DC stamp or store signature (or a BOL without a carrier signature) as invalid for shortages.', 'Request the stamped or signed copy from the carrier using the PRO number.', 'logistics', 'https://help.supplypike.com/en/articles/4993182-example-shipping-documents'),
  ('shortage_wmt-5', 'shortage_wmt', 5, 'Amounts', 'Amounts reconcile exactly', 20, 'amount_matches', true, true, 'A dispute amount that doesn''t match its backup is rejected even when the claim is valid.', 'Set the dispute amount to the documented shortage, to the cent.', 'analyst', 'https://www.emagia.com/blog/walmart-deduction-dispute-process-guide/'),
  ('shortage_wmt-6', 'shortage_wmt', 6, 'Procedural', 'Proof type fits prepaid or collect', 5, 'proof_type_fits', false, false, 'Prepaid shipments need a POD; collect shipments need a carrier-signed BOL.', 'Attach the proof type that matches the shipment terms.', 'logistics', 'https://help.supplypike.com/en/articles/4993182-example-shipping-documents'),
  ('shortage_wmt-7', 'shortage_wmt', 7, 'Procedural', 'Deduction settled', 5, 'settled', false, false, 'Disputing before a deduction settles can produce approvals that are later reversed.', 'Wait until the deduction shows as posted, then submit.', 'analyst', 'https://www.spscommerce.com/community/articles/why-deduction-documents-get-rejected-fixes'),
  ('shortage_wmt-8', 'shortage_wmt', 8, 'History', 'Prior denial addressed', 10, 'prior_denial_addressed', false, false, 'A re-dispute must fix what the last denial said was wrong.', 'Add the evidence the previous denial asked for.', 'analyst', null),
  ('shortage_amz-1', 'shortage_amz', 1, 'Evidence present', 'Required documents present', 35, 'docs_present', true, true, 'A dispute without its required documents is denied.', 'Attach the missing document.', 'analyst', 'https://www.channelengine.com/en/blog/disputing-shortage-claims-on-amazon-vendor'),
  ('shortage_amz-2', 'shortage_amz', 2, 'Evidence content', 'PO number matches', 8, 'po_matches', false, false, 'Every document must point to the PO being disputed.', 'Get a corrected delivery confirmation showing the right PO.', 'logistics', null),
  ('shortage_amz-3', 'shortage_amz', 3, 'Evidence content', 'Ship-to matches', 8, 'shipto_matches', false, false, 'The delivery must be to the fulfillment center on the PO.', 'Confirm the delivery FC with the carrier.', 'logistics', null),
  ('shortage_amz-4', 'shortage_amz', 4, 'Evidence content', 'Delivery confirmed by carrier', 9, 'delivery_confirmed', true, false, 'Amazon needs proof the shipment reached the fulfillment center.', 'Get the carrier''s delivery confirmation with tracking.', 'logistics', 'https://www.channelengine.com/en/blog/disputing-shortage-claims-on-amazon-vendor'),
  ('shortage_amz-5', 'shortage_amz', 5, 'Amounts', 'Amounts reconcile exactly', 20, 'amount_matches', true, true, 'A dispute amount that doesn''t match its backup is rejected.', 'Set the dispute amount to the documented shortage, to the cent.', 'analyst', 'https://www.emagia.com/blog/walmart-deduction-dispute-process-guide/'),
  ('shortage_amz-6', 'shortage_amz', 6, 'Procedural', 'Related claims grouped', 5, 'grouped', false, false, 'Claims for the same PO should be disputed together.', 'Group this claim with the other claims on the same PO.', 'analyst', null),
  ('shortage_amz-7', 'shortage_amz', 7, 'Procedural', 'Dispute summary written', 5, 'summary_written', false, false, 'Amazon asks for a written explanation of why the claim is wrong.', 'Write or accept the AI-drafted summary.', 'analyst', 'https://www.spscommerce.com/community/articles/chargeback-recovery'),
  ('shortage_amz-8', 'shortage_amz', 8, 'History', 'Prior denial addressed', 10, 'prior_denial_addressed', false, false, 'A re-dispute must fix what the last denial said was wrong.', 'Add the evidence the previous denial asked for.', 'analyst', null),
  ('pricing_wmt-1', 'pricing_wmt', 1, 'Evidence present', 'Required documents present', 35, 'docs_present', true, true, 'Pricing disputes need the invoice, the claim and the PO.', 'Download the claim from APDP/APIS and attach it.', 'analyst', 'https://help.supplypike.com/en/articles/4988093-recommended-proof-documentation-for-wal-mart-disputing'),
  ('pricing_wmt-2', 'pricing_wmt', 2, 'Evidence content', 'PO number matches', 8, 'po_matches', false, false, 'The claim and invoice must reference the PO being disputed.', 'Check the claim''s PO reference; correct the dispute if it was filed against the wrong PO.', 'analyst', null),
  ('pricing_wmt-3', 'pricing_wmt', 3, 'Evidence content', 'Item number matches PO', 8, 'item_matches', false, false, 'An item mismatch suggests a substitution, which is a different code.', 'Confirm the item shipped; if substituted, this may be Code 13, not 11.', 'sales', null),
  ('pricing_wmt-4', 'pricing_wmt', 4, 'Evidence content', 'Invoice price matches PO price', 9, 'price_matches', true, true, 'If you invoiced above the PO price, Walmart''s deduction is probably valid.', 'Review with sales. If the PO price was right, accept and write off; fix the price file.', 'sales', 'https://www.spscommerce.com/community/articles/why-deduction-documents-get-rejected-fixes'),
  ('pricing_wmt-5', 'pricing_wmt', 5, 'Amounts', 'Amounts reconcile exactly', 20, 'amount_matches', true, true, 'A dispute amount that doesn''t match its backup is rejected.', 'Set the dispute amount to the documented difference.', 'analyst', 'https://www.emagia.com/blog/walmart-deduction-dispute-process-guide/'),
  ('pricing_wmt-6', 'pricing_wmt', 6, 'Procedural', 'Deduction settled', 5, 'settled', false, false, 'Disputing before a deduction settles can produce reversed approvals.', 'Wait until the deduction shows as posted.', 'analyst', null),
  ('pricing_wmt-7', 'pricing_wmt', 7, 'Procedural', 'Dispute summary written', 5, 'summary_written', false, false, 'An explanation helps the reviewer see the price agreement.', 'Write or accept the AI-drafted summary.', 'analyst', null),
  ('pricing_wmt-8', 'pricing_wmt', 8, 'History', 'Prior denial addressed', 10, 'prior_denial_addressed', false, false, 'A re-dispute must fix what the last denial said was wrong.', 'Add the evidence the previous denial asked for.', 'analyst', null),
  ('asn_amz-1', 'asn_amz', 1, 'Evidence present', 'Required documents present', 35, 'docs_present', true, true, 'Amazon needs the ASN screenshot or EDI 856 file.', 'Export the EDI 856 (text or XML) or screenshot it in Vendor Central.', 'analyst', 'https://www.spscommerce.com/community/articles/chargeback-recovery'),
  ('asn_amz-2', 'asn_amz', 2, 'Evidence content', 'PO number matches', 8, 'po_matches', false, false, 'The ASN must reference the PO on the chargeback.', 'Attach the ASN for the correct PO.', 'analyst', null),
  ('asn_amz-3', 'asn_amz', 3, 'Evidence content', 'Carton IDs present (SSCC or AMZNCC)', 8, 'carton_ids_present', false, false, 'Amazon checks that the ASN carried carton-level barcode data.', 'Show where the ASN contained the SSCC or AMZNCC values.', 'logistics', 'https://wiki.amazowl.com/sop/vendor-central/dispute-chargeback-ASN'),
  ('asn_amz-4', 'asn_amz', 4, 'Evidence content', 'ASN sent before receipt', 9, 'sent_before_receipt', true, true, 'The ASN must have been sent before Amazon received the shipment.', 'If it was sent late, the chargeback is probably valid; accept it and fix the ASN timing.', 'logistics', 'https://www.spscommerce.com/community/articles/chargeback-recovery'),
  ('asn_amz-5', 'asn_amz', 5, 'Amounts', 'Amounts reconcile exactly', 20, 'amount_matches', true, true, 'The disputed amount must equal the chargeback amount.', 'Set the dispute amount to the chargeback amount.', 'analyst', null),
  ('asn_amz-6', 'asn_amz', 6, 'Procedural', 'Related chargebacks grouped', 5, 'grouped', false, false, 'Chargebacks for the same ASIN or PO can be disputed together.', 'Select the related chargebacks in the same dispute.', 'analyst', 'https://www.spscommerce.com/community/articles/chargeback-recovery'),
  ('asn_amz-7', 'asn_amz', 7, 'Procedural', 'Dispute summary written', 5, 'summary_written', false, false, 'Amazon asks for a written explanation in the dispute summary.', 'Write or accept the AI-drafted summary.', 'analyst', 'https://www.spscommerce.com/community/articles/chargeback-recovery'),
  ('asn_amz-8', 'asn_amz', 8, 'History', 'Prior denial addressed', 10, 'prior_denial_addressed', false, false, 'Amazon allows only two disputes; the second must add new evidence.', 'Add the evidence the previous denial asked for.', 'analyst', 'https://www.amalytix.com/en/glossary/chargebacks/'),
  ('carton_amz-1', 'carton_amz', 1, 'Evidence present', 'Required documents present', 35, 'docs_present', true, true, 'Amazon needs photos of the carton contents.', 'Photograph an opened carton from the same shipment.', 'warehouse', 'https://wiki.amazowl.com/sop/vendor-central/dispute-chargeback-ASN'),
  ('carton_amz-2', 'carton_amz', 2, 'Evidence content', 'Carton visibly opened', 8, 'carton_opened', true, false, 'Amazon asks for a face-open carton; a sealed box shows nothing.', 'Retake the photo with the carton opened.', 'warehouse', 'https://wiki.amazowl.com/sop/vendor-central/dispute-chargeback-ASN'),
  ('carton_amz-3', 'carton_amz', 3, 'Evidence content', 'Barcodes legible, match the ASIN', 8, 'barcode_legible', false, false, 'Barcodes must be readable to prove the labeling was right.', 'Retake the photo closer, with the barcode in focus.', 'warehouse', 'https://www.spscommerce.com/community/articles/chargeback-recovery'),
  ('carton_amz-4', 'carton_amz', 4, 'Evidence content', 'Inner packs and units visible', 9, 'units_visible', true, true, 'Amazon asks for images showing inner packs and individual sellable units.', 'Retake the photo showing inner packs and units.', 'warehouse', 'https://wiki.amazowl.com/sop/vendor-central/dispute-chargeback-ASN'),
  ('carton_amz-5', 'carton_amz', 5, 'Amounts', 'Amounts reconcile exactly', 20, 'amount_matches', true, true, 'The disputed amount must equal the chargeback amount.', 'Set the dispute amount to the chargeback amount.', 'analyst', null),
  ('carton_amz-6', 'carton_amz', 6, 'Procedural', 'Related chargebacks grouped', 5, 'grouped', false, false, 'Chargebacks for the same ASIN or PO can be disputed together.', 'Select the related chargebacks in the same dispute.', 'analyst', null),
  ('carton_amz-7', 'carton_amz', 7, 'Procedural', 'Dispute summary written', 5, 'summary_written', false, false, 'Amazon asks for a written explanation in the dispute summary.', 'Write or accept the AI-drafted summary.', 'analyst', null),
  ('carton_amz-8', 'carton_amz', 8, 'History', 'Prior denial addressed', 10, 'prior_denial_addressed', false, false, 'Amazon allows only two disputes; the second must add new evidence.', 'Add the evidence the previous denial asked for.', 'analyst', 'https://www.amalytix.com/en/glossary/chargebacks/');
